/**
 * When a workspace is read-only because its subscription is not in good standing.
 *
 * `lockReasonFor` is the only statement of the rule. Billing summaries and
 * `assertWorkspaceWritable` both call it, so the banner and the write guard
 * cannot disagree.
 */
import type { Subscription, WorkspaceLockReason } from "@/types/billing";
import type { OrgId } from "@/types/common";

/** A member write was refused because the workspace is locked. */
export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(`This workspace is read-only (${reason}).`);
    this.name = "WorkspaceLockedError";
  }
}

/**
 * The lock rule, evaluated at `now` (defaulting to the current time) against
 * the subscription as stored.
 *
 * No row, or `active`, is writable. `past_due` is locked immediately.
 * `trialing` locks at the period end. `canceled` locks at `cancelAt`, and a
 * canceled row with no cancellation date is locked now. A cancellation dated
 * in the future stays writable until that moment.
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null || subscription.status === "active") {
    return null;
  }

  if (subscription.status === "past_due") {
    return "past_due";
  }

  if (subscription.status === "trialing") {
    return reached(subscription.currentPeriodEnd, now) ? "trial_ended" : null;
  }

  if (subscription.status === "canceled") {
    if (subscription.cancelAt === null) return "canceled";
    return reached(subscription.cancelAt, now) ? "canceled" : null;
  }

  return null;
}

/** True when `instant` is at or before `now`. */
function reached(instant: string, now: Date): boolean {
  return now.getTime() >= new Date(instant).getTime();
}

