/**
 * Refuses a member write while the workspace is locked at `now`.
 * Billing changes, deletion, notification housekeeping and Taskflow's own jobs
 * do not call this — they are the ways out of the lock, or they are not member
 * writes.
 */
export async function assertWorkspaceWritable(
  orgId: OrgId,
  now: Date = new Date(),
): Promise<void> {
  const reason = lockReasonFor(
    await subscriptionRepo.findSubscription(orgId),
    now,
  );
  if (reason !== null) {
    throw new WorkspaceLockedError(orgId, reason);
  }
}

